import { formatDate } from '../utils/dates.js'

const MOCK_ANALYSIS =
  'Mock AI analysis — integration will be connected during the AI integration stage. This bounded preview is for human review only and is not generated by a live AI provider.'

const MOCK_NEXT_STEP = 'Review the lead and schedule the next follow-up.'

function activity(id, type, title, description, time, status) {
  return { id, type, title, description, time, status }
}

export function createLeadRecord(fields, options = {}) {
  const now = options.createdAt ? new Date(options.createdAt) : new Date()
  const id = options.id || `lead-${now.getTime()}`
  const createdLabel = formatDate(now)
  const analysisFailed = Boolean(options.analysisFailed)
  const analysisPending = Boolean(options.analysisPending)

  const activities = [
    activity(
      `${id}-created`,
      'lead_added',
      'Lead created',
      `${fields.name} was added to CRM.`,
      createdLabel,
      fields.status || 'New',
    ),
  ]

  if (analysisPending) {
    activities.push(
      activity(
        `${id}-analyzed`,
        'lead_analyzed',
        'Lead analysis pending',
        'Mock analysis has not been recorded yet. A real AI provider is not connected.',
        createdLabel,
        'Pending',
      ),
    )
  } else if (analysisFailed) {
    activities.push(
      activity(
        `${id}-analyzed`,
        'lead_analyzed',
        'Lead analysis failed',
        'Mock analysis failed. The lead was still saved. A real AI provider is not connected.',
        createdLabel,
        'Failed',
      ),
    )
  } else {
    activities.push(
      activity(
        `${id}-analyzed`,
        'lead_analyzed',
        'Lead analyzed',
        'Mock analysis was saved for human review. A real AI provider is not connected.',
        createdLabel,
        'Succeeded',
      ),
    )
    activities.push(
      activity(
        `${id}-task`,
        'task_created',
        'Follow-up task created',
        'Review lead and follow up.',
        createdLabel,
        'Pending',
      ),
    )
  }

  return {
    id,
    name: fields.name.trim(),
    email: fields.email?.trim() || '',
    phone: fields.phone?.trim() || '',
    company: fields.company?.trim() || '',
    status: fields.status,
    notes: fields.notes?.trim() || '',
    createdAt: now.toISOString(),
    createdLabel,
    updatedAt: now.toISOString(),
    aiAnalysis: {
      isMock: true,
      status: analysisPending ? 'pending' : analysisFailed ? 'failed' : 'available',
      summary: analysisPending || analysisFailed ? '' : MOCK_ANALYSIS,
    },
    suggestedNextStep: analysisPending || analysisFailed ? '' : MOCK_NEXT_STEP,
    followUpTask:
      analysisPending || analysisFailed
        ? null
        : {
            status: 'Pending',
            task: 'Review lead and follow up',
            created: createdLabel,
          },
    activities,
  }
}

